create table if not exists public.system_zenkaku_submission (id uuid primary key default gen_random_uuid(),check_request_id uuid not null references public.system_zenkaku_check_request(id),sales_id text not null,requested_by uuid not null references auth.users(id),requester_name text not null,selected_partner_code text,duplicate_confirmed boolean not null default false,status text not null default 'pending' check(status in('pending','reading','needs_partner','needs_confirmation','done','failed')),candidates jsonb,case_id text,error_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists idx_system_zenkaku_submission_active on public.system_zenkaku_submission(check_request_id) where status not in('done','failed'); alter table public.system_zenkaku_submission enable row level security;
create policy system_zenkaku_submission_own on public.system_zenkaku_submission for select to authenticated using(requested_by=auth.uid() or public.has_role_at_least('manager')); grant select on public.system_zenkaku_submission to authenticated; grant all on public.system_zenkaku_submission to service_role;
create table if not exists public.system_zenkaku_case_sequence(year_code text primary key,last_sequence integer not null); grant all on public.system_zenkaku_case_sequence to service_role;
create or replace function public.system_zenkaku_reserve_case_sequence(p_year_code text,p_observed integer) returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin insert into system_zenkaku_case_sequence values(p_year_code,p_observed) on conflict(year_code) do update set last_sequence=greatest(system_zenkaku_case_sequence.last_sequence,excluded.last_sequence); update system_zenkaku_case_sequence set last_sequence=last_sequence+1 where year_code=p_year_code returning last_sequence into n; return n; end $$;
revoke all on function public.system_zenkaku_reserve_case_sequence(text,integer) from public,anon,authenticated; grant execute on function public.system_zenkaku_reserve_case_sequence(text,integer) to service_role;
create or replace function public.system_zenkaku_submit_claim_next() returns table(id uuid,sales_id text) language plpgsql security definer set search_path=public as $$ begin update system_zenkaku_submission set status='failed',error_code='timeout',updated_at=now() where status='reading' and updated_at<now()-interval '60 seconds'; return query with c as(select s.id from system_zenkaku_submission s where s.status='pending' order by s.created_at for update skip locked limit 1) update system_zenkaku_submission s set status='reading',updated_at=now() from c where s.id=c.id returning s.id,s.sales_id; end $$;
revoke all on function public.system_zenkaku_submit_claim_next() from public,anon,authenticated; grant execute on function public.system_zenkaku_submit_claim_next() to service_role;
